using Avalonia;
using Avalonia.Controls;
using Avalonia.Input;
using Avalonia.Input.Raw;
using Avalonia.Media.Imaging;
using Avalonia.VisualTree;
using LtcPlayer.App;
using System.Text.Json;
namespace LtcPlayer.Avalonia;

public static class DisplayColumnsVerification
{
 public static async Task RunAsync(MainWindow w,string folder)
 {
  Directory.CreateDirectory(folder);bool failed=false;var results=new List<object>();
  var grid=w.FindControl<DataGrid>("CueGrid")!;var video=grid.Columns.Single(c=>c.Header?.ToString()=="動画");var status=grid.Columns.Single(c=>c.Header?.ToString()=="ステータス");
  var fixedColumns=grid.Columns.Where(c=>c!=video&&c!=status).ToArray();
  void Check(bool ok,string why){if(!ok)throw new IOException(why);}
  async Task Test(string name,Func<Task> body){try{await body();results.Add(new{test=name,status="PASS"});}catch(Exception e){failed=true;results.Add(new{test=name,status="FAIL",detail=e.ToString()});}File.WriteAllText(Path.Combine(folder,"results.json"),JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));}
  DataGridColumnHeader Header(DataGridColumn column)=>grid.GetVisualDescendants().OfType<DataGridColumnHeader>().First(h=>h.Bounds.Width>0&&h.Content?.ToString()==column.Header?.ToString());
  async Task Drag(DataGridColumn column,double delta){Control header=column==video?grid.GetVisualDescendants().OfType<Border>().Single(b=>b.Classes.Contains("cue-column-resizer")):Header(column);var pointer=new Pointer(77,PointerType.Mouse,true);var start=new Point(header.Bounds.Width-2,header.Bounds.Height/2);var end=new Point(start.X+delta,start.Y);header.RaiseEvent(new PointerPressedEventArgs(header,pointer,header,start,0,new PointerPointProperties(RawInputModifiers.LeftMouseButton,PointerUpdateKind.LeftButtonPressed),KeyModifiers.None,1));header.RaiseEvent(new PointerEventArgs(InputElement.PointerMovedEvent,header,pointer,header,end,1,new PointerPointProperties(RawInputModifiers.LeftMouseButton,PointerUpdateKind.Other),KeyModifiers.None));header.RaiseEvent(new PointerReleasedEventArgs(header,pointer,header,end,2,new PointerPointProperties(RawInputModifiers.None,PointerUpdateKind.LeftButtonReleased),KeyModifiers.None,MouseButton.Left));await Task.Delay(100);}
  void Capture(string name){using var image=new RenderTargetBitmap(new PixelSize((int)w.ClientSize.Width,(int)w.ClientSize.Height),new Vector(96,96));image.Render(w);image.Save(Path.Combine(folder,name+".png"));}
  void CheckHeaders()
  {
   var headers=grid.Columns.Select(Header).ToArray();
   for(int i=0;i<headers.Length-1;i++){
    var header=headers[i];var separator=header.GetVisualDescendants().OfType<global::Avalonia.Controls.Shapes.Rectangle>().Single(r=>r.Name=="VerticalSeparator");
    Check(separator.IsVisible&&separator.Bounds.Width>0&&separator.Bounds.Height>=header.Bounds.Height-1,"header separator missing");
    Check(header.Bounds.Right<=headers[i+1].Bounds.Left+.01,$"header overlaps separator: {header.Content}");
   }
   var menu=headers.Single(h=>h.Content?.ToString()=="開始TC").GetVisualDescendants().OfType<Button>().Single();
   var dots=menu.GetVisualDescendants().OfType<global::Avalonia.Controls.Shapes.Ellipse>().ToArray();
   Check(dots.Length==3,"menu dots missing");
   foreach(var dot in dots){var center=dot.TranslatePoint(new Point(dot.Bounds.Width/2,dot.Bounds.Height/2),menu)!.Value;Check(Math.Abs(center.Y-menu.Bounds.Height/2)<.01,"menu dots are not vertically centered");}
  }
  var row=new CueRow{FilePath=Path.Combine(Program.Option("--fixtures")!,"h264-aac.mp4")};
  try{
   await Test("Windows device names become readable without changing identity",()=>{var display=new OutputDisplay{Name=@"\\.\DISPLAY12",Width=1920,Height=1080,Primary=1,X=-1920};Check(display.ToString()=="ディスプレイ 12  1920×1080 · メイン"&&display.Name==@"\\.\DISPLAY12","display key or label changed");Check(OutputDisplay.Label(@"\\.\display2")=="ディスプレイ 2"&&OutputDisplay.Label("Projector")=="Projector"&&OutputDisplay.Label(null)=="ディスプレイ","fallback labels");return Task.CompletedTask;});
   await Test("connected disconnected and unselected choices remain distinct",()=>{var display=VideoRenderer.Displays().First();var connected=new OutputDisplayChoice(display,display.Name,true);var missing=new OutputDisplayChoice(null,@"\\.\DISPLAY9",false);Check(!connected.ToString().Contains(@"\\.\")&&connected.Name==display.Name,"connected key leaked or changed");Check(missing.ToString()=="ディスプレイ 9（未接続）"&&missing.Name==@"\\.\DISPLAY9","disconnected choice wrong");Check(new OutputDisplayChoice(null,null,false).ToString()=="未選択","unselected choice wrong");return Task.CompletedTask;});
   await Test("saved display stays a raw device key and settings are not dirty on open",async()=>{var display=VideoRenderer.Displays().First();string path=Path.Combine(folder,"identity.json");using(var pending=new PendingSettings(path,new(),display.Name))pending.Commit();using(var doc=JsonDocument.Parse(File.ReadAllText(path)))Check(doc.RootElement.GetProperty("OutputDisplayName").GetString()==display.Name,"persisted friendly label");var dialog=new SettingsDialog(new(),display,false,displayName:display.Name);var task=dialog.ShowDialog<SettingsResult?>(w);try{await Task.Delay(100);Check(!dialog.ApplyButton.IsEnabled&&dialog.OutputSelector.SelectedItem is OutputDisplayChoice choice&&choice.Name==display.Name,"rename changed selected device or dirty state");using var image=new RenderTargetBitmap(new PixelSize((int)dialog.ClientSize.Width,(int)dialog.ClientSize.Height),new Vector(96,96));var tabs=dialog.GetVisualDescendants().OfType<TabControl>().Single();tabs.SelectedIndex=2;await Task.Delay(60);image.Render(dialog);image.Save(Path.Combine(folder,"display-settings.png"));}finally{dialog.Close(null);await task;}});
   await ShowProgramService.RefreshAsync(row,CancellationToken.None);w.Editor.Add(row);grid.SelectedItem=row;await Task.Delay(150);
   await Test("only video column is directly resizable and headers are aligned before resizing",()=>{CheckHeaders();Capture("initial-headers");Check(!grid.CanUserResizeColumns&&grid.GetVisualDescendants().OfType<Border>().Count(b=>b.Classes.Contains("cue-column-resizer"))==1,"unexpected resize permissions");return Task.CompletedTask;});
   await Test("drag redistributes video and status widths without resizing other columns",async()=>{var widths=fixedColumns.Select(c=>c.ActualWidth).ToArray();double beforeVideo=video.ActualWidth,beforeStatus=status.ActualWidth;var session=w.Preview.PlaybackSessionId;await Drag(video,60);Check(video.ActualWidth>beforeVideo+30&&status.ActualWidth<beforeStatus-30,$"drag did not redistribute widths: video {beforeVideo} -> {video.ActualWidth}; status {beforeStatus} -> {status.ActualWidth}");Check(Math.Abs(video.ActualWidth+status.ActualWidth-beforeVideo-beforeStatus)<2,"combined width changed");Check(fixedColumns.Select((c,i)=>Math.Abs(c.ActualWidth-widths[i])<1).All(x=>x),"fixed column changed");Check(grid.SelectedItem==row&&w.Preview.PlaybackSessionId==session&&w.Preview.LoadedPath=="","resize affected selection or playback");CheckHeaders();Capture("video-wider");await Drag(video,-100);Check(status.ActualWidth>beforeStatus+20,"reverse drag did not widen status");CheckHeaders();Capture("status-wider");});
   await Test("dragging fixed headers and minimum widths cannot collapse controls",async()=>{var fixedColumn=fixedColumns.First(c=>c.Header?.ToString()=="開始TC");double width=fixedColumn.ActualWidth;await Drag(fixedColumn,80);Check(Math.Abs(fixedColumn.ActualWidth-width)<1,"fixed header resized");await Drag(video,10000);Check(status.ActualWidth>=status.MinWidth-1&&video.ActualWidth>=video.MinWidth-1,"status minimum lost");await Drag(video,-10000);Check(Math.Abs(video.ActualWidth-90)<1&&status.ActualWidth>=status.MinWidth-1,"video cannot reach the 90px minimum");});
   await Test("window resize and narrow scroll keep fixed columns and both text columns usable",async()=>{var widths=fixedColumns.Select(c=>c.ActualWidth).ToArray();foreach(var size in new[]{(1800,950),(700,1100),(1640,900)}){w.Width=size.Item1;w.Height=size.Item2;await Task.Delay(200);CheckHeaders();Check(video.ActualWidth>=video.MinWidth-1&&status.ActualWidth>=status.MinWidth-1,"text columns collapsed");Check(fixedColumns.Select((c,i)=>Math.Abs(c.ActualWidth-widths[i])<1).All(x=>x),"window resize changed fixed columns");}Capture("restored-wide");});
   await Test("resize during external manual playback preserves video audio and output sessions",async()=>{await w.ApplySettingsAsync(new(new(Rate:"25"),VideoRenderer.Displays().First(d=>d.Primary!=0)));await w.ArmAsync();await w.SetSharedAudioAsync(true,silenceForVerification:true);await w.PlayCueForTestAsync(row);double end=MasterClock.Timestamp()+6;while(w.Coordinator.Audio.State!=SharedAudioState.Playing){if(MasterClock.Timestamp()>end)throw new TimeoutException("audio not ready");await Task.Delay(10);}var source=w.Preview.PlaybackSessionId;var canvas=w.Surface.Canvas.SessionId;var audio=w.Coordinator.Audio.SinkSession;int preparations=w.Coordinator.Audio.PreparationStarts;await Drag(video,40);Check(w.IsOutputActive&&w.Preview.PlaybackSessionId==source&&w.Surface.Canvas.SessionId==canvas&&w.Coordinator.Audio.SinkSession==audio&&w.Coordinator.Audio.PreparationStarts==preparations,"resize restarted playback resources");var handle=grid.GetVisualDescendants().OfType<Border>().Single(b=>b.Classes.Contains("cue-column-resizer"));var pointer=new Pointer(78,PointerType.Mouse,true);handle.RaiseEvent(new PointerPressedEventArgs(handle,pointer,handle,new Point(2,10),0,new PointerPointProperties(RawInputModifiers.LeftMouseButton,PointerUpdateKind.LeftButtonPressed),KeyModifiers.None,1));w.RaiseEvent(new KeyEventArgs{RoutedEvent=InputElement.KeyDownEvent,Key=Key.Escape});Check(pointer.Captured==null&&w.IsOutputActive&&w.Preview.Snapshot.State==PreviewState.Playing,"Escape stopped playback instead of finishing resize");Capture("playing-resized");await w.DisarmAsync();});
  }catch(Exception e){failed=true;File.WriteAllText(Path.Combine(folder,"fatal.txt"),e.ToString());}
  finally{await w.DisarmAsync();await w.Coordinator.DisposeAsync();await w.Preview.DisposeAsync();await w.Monitor.DisposeAsync();MainWindow.Shutdown(failed?1:0);}
 }
}
